def fill_rect(self, x, y, w, h, color):
    """Use the ST7796-supported RAM-continue path for solid fills."""
    color_bytes = (
        (color & 0xFFFF).to_bytes(2, "big")
        if self._auto_byteswap
        else (color & 0xFFFF).to_bytes(2, "little")
    )
    x1 = x + self.colstart
    x2 = x1 + w - 1
    y1 = y + self.rowstart
    y2 = y1 + h - 1
    if h > w:
        buf = self._fill_strip(h, color_bytes)
        passes = w
    else:
        buf = self._fill_strip(w, color_bytes)
        passes = h
    self._set_window(x1, y1, x2, y2)
    self.send(_RAMWR)
    for unused in range(passes):
        self.send_color(_RAMCONT, buf)
    return (x, y, w, h)

